using KernelOS.Core.Kai; namespace KernelOS.Infrastructure.Kai; public sealed class DeterministicKaiIntentRouter:IKaiIntentRouter { public KaiDecision Route(string message,KaiMode preferredMode) { if(preferredMode!=KaiMode.Auto)return new(preferredMode,"EXPLICIT_MODE"); var text=message.ToLowerInvariant(); return text.Contains("en mis documentos",StringComparison.Ordinal)||text.Contains("según el documento",StringComparison.Ordinal)||text.Contains("segun el documento",StringComparison.Ordinal)||text.Contains("en los archivos",StringComparison.Ordinal)?new(KaiMode.Rag,"KNOWLEDGE_QUERY"):new(KaiMode.Chat,"DEFAULT_CHAT"); } }
